_DOCUMENTATION_SUFFIXES = {".md": "markdown", ".txt": "text"}
_SOURCE_ID_PATTERN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$")


@dataclass(frozen=True)
class _LoadedDocumentation:
    source_id: str
    display_name: str
    document_type: str
    status: str
    size_bytes: int | None = None
    line_count: int | None = None
    sha256: str | None = None
    text: str | None = None
    error_code: EvidenceErrorCode | None = None


class EvidenceSession:
    """Expose only bounded, deterministic evidence to a future semantic agent.

    Source excerpts are disabled unless the trusted host opts in at session creation. Even then,
    callers identify only profiled runs and variables; source paths are resolved internally.
    """

    def __init__(
        self,
        profile: DatasetProfile,
        *,
        limits: EvidenceLimits | None = None,
        budget: EvidenceBudget | None = None,
        allow_bounded_source_excerpts: bool = False,
        documentation_sources: list[DocumentationSource]
        | tuple[DocumentationSource, ...]
        | None = None,
    ) -> None:
        self._profile = profile
        self.limits = limits or EvidenceLimits()
        self.budget = budget or EvidenceBudget()
        self._validate_configuration()
        self._allow_excerpts = allow_bounded_source_excerpts
        self._total_queries = 0
        self._excerpt_queries = 0
        self._excerpt_values = 0
        self._documentation_queries = 0
        self._documentation_chars = 0
        self._profile_fingerprint = hashlib.sha256(
            profile.to_json().encode()
        ).hexdigest()[:16]
        self._registered_documentation_count = len(documentation_sources or ())
        self._documentation = self._load_documentation(documentation_sources or ())

    @property
    def usage(self) -> EvidenceUsage:
        return EvidenceUsage(
            self._total_queries,
            self._excerpt_queries,
            self._excerpt_values,
            self._documentation_queries,
            self._documentation_chars,
        )

    def documentation_sources(self) -> EvidenceResponse:
        """Describe explicitly registered documents without exposing their paths or contents."""
        kind = EvidenceKind.DOCUMENTATION_SOURCES
        if error := self._begin(kind):
            return error
        items = []
        for source in self._documentation:
            item: dict[str, Any] = {
                "source_id": source.source_id,
                "display_name": source.display_name,
                "document_type": source.document_type,
                "status": source.status,
            }
            if source.size_bytes is not None:
                item["size_bytes"] = source.size_bytes
            if source.line_count is not None:
                item["line_count"] = source.line_count
            if source.sha256 is not None:
                item["sha256"] = source.sha256
            if source.error_code is not None:
                item["error_code"] = source.error_code.value
            items.append(item)
        value = {
            "items": items,
            "returned": len(items),
            "registered": self._registered_documentation_count,
            "truncated": len(items) < self._registered_documentation_count,
        }
        return self._evidence(kind, "documentation_registry", "dataset", None, value)

    def documentation_search(
        self,
        query: str,
        *,
        max_results: int = 3,
    ) -> DocumentationSearchResponse:
        """Return bounded literal/token matches from host-registered text documents."""
        kind = EvidenceKind.DOCUMENTATION
        if error := self._begin(kind):
            return error
        if not isinstance(query, str) or not query.strip() or len(query) > 200:
            return self._error(
                EvidenceErrorCode.INVALID_QUERY,
                kind,
                "query must be a non-empty string of at most 200 characters",
            )
        if (
            isinstance(max_results, bool)
            or not isinstance(max_results, int)
            or max_results <= 0
        ):
            return self._error(
                EvidenceErrorCode.INVALID_QUERY,
                kind,
                "max_results must be a positive integer",
            )
        if self._documentation_queries >= self.budget.max_documentation_queries:
            return self._error(
                EvidenceErrorCode.QUERY_BUDGET_EXCEEDED,
                kind,
                "The session's documentation-query budget is exhausted.",
                limit=self.budget.max_documentation_queries,
                used=self._documentation_queries,
            )
        if self._documentation_chars >= self.budget.max_total_documentation_chars:
            return self._error(
                EvidenceErrorCode.DOCUMENTATION_BUDGET_EXCEEDED,
                kind,
                "The session's documentation-character budget is exhausted.",
                limit=self.budget.max_total_documentation_chars,
                used=self._documentation_chars,
            )
        self._documentation_queries += 1
        available = [
            source for source in self._documentation if source.text is not None
        ]
        if not available:
            statuses = {source.status for source in self._documentation}
            if statuses == {"unsupported"}:
                code = EvidenceErrorCode.UNSUPPORTED_DOCUMENTATION
            elif statuses == {"invalid"}:
                code = EvidenceErrorCode.INVALID_DOCUMENTATION_SOURCE
            else:
                code = EvidenceErrorCode.UNAVAILABLE_DOCUMENTATION
            return self._error(
                code,
                kind,
                "No readable, supported documentation is available for this session.",
                registered=self._registered_documentation_count,
            )

        cleaned_query = " ".join(query.strip().split())
        normalized_query = cleaned_query.casefold()
        query_tokens = re.findall(r"\w+", normalized_query)
        candidates: list[
            tuple[int, str, int, _LoadedDocumentation, int, int, str, bool]
        ] = []
        for source in available:
            assert source.text is not None
            lines = source.text.splitlines()
            for index, line in enumerate(lines):
                rank = self._documentation_match_rank(
                    line, cleaned_query, normalized_query, query_tokens
                )
                if rank is None:
                    continue
                start = max(0, index - 1)
                end = min(len(lines), index + 2)
                raw_excerpt = "\n".join(lines[start:end])
                excerpt, truncated = self._bounded_excerpt_text(
                    raw_excerpt,
                    line,
                    cleaned_query,
                    self.limits.max_documentation_excerpt_chars,
                )
                candidates.append(
                    (
                        rank,
                        source.source_id,
                        index,
                        source,
                        start,
                        end,
                        excerpt,
                        truncated,
                    )
                )

        candidates.sort(key=lambda item: (item[0], item[1].casefold(), item[2]))
        result_limit = min(max_results, self.limits.max_documentation_results)
        results: list[Evidence] = []
        returned_chars = 0
        seen_locations: set[tuple[str, int, int]] = set()
        for rank, _, index, source, start, end, excerpt, truncated in candidates:
            location = (source.source_id, start, end)
            if location in seen_locations:
                continue
            remaining_query_chars = (
                self.limits.max_documentation_response_chars - returned_chars
            )
            remaining_session_chars = (
                self.budget.max_total_documentation_chars
                - self._documentation_chars
                - returned_chars
            )
            allowance = min(remaining_query_chars, remaining_session_chars)
            if allowance <= 0:
                break
            if len(excerpt) > allowance:
                excerpt = excerpt[:allowance].rstrip() + ("…" if allowance > 1 else "")
                excerpt = excerpt[:allowance]
                truncated = True
            value = {
                "query": cleaned_query,
                "source_id": source.source_id,
                "display_name": source.display_name,
                "document_type": source.document_type,
                "excerpt": excerpt,
                "line_start": start + 1,
                "line_end": end,
                "match_line": index + 1,
                "excerpt_truncated": truncated,
            }
            evidence = self._evidence(
                kind,
                source.source_id,
                "documentation",
                cleaned_query,
                value,
                query={
                    "query": normalized_query,
                    "source_sha256": source.sha256,
                    "line_start": start + 1,
                    "line_end": end,
                },
                metadata={"document_sha256": source.sha256},
            )
            if isinstance(evidence, EvidenceError):
                return evidence
            results.append(evidence)
            seen_locations.add(location)
            returned_chars += len(excerpt)
            if len(results) >= result_limit:
                break

        self._documentation_chars += returned_chars
        return results

    def dataset_summary(self) -> EvidenceResponse:
        kind = EvidenceKind.DATASET_SUMMARY
        if error := self._begin(kind):
            return error
        variables = sorted(self._profile.observed_structure.get("variable_schema", {}))
        variable_page = self._bounded_list(variables, self.limits.max_metadata_entries)
        rates = sorted(
            {
                run.sampling_rate_hz
                for run in self._profile.runs
                if run.sampling_rate_hz is not None
            }
        )
        lengths = sorted(
            {
                run.sequence_length
                for run in self._profile.runs
                if run.sequence_length is not None
            }
        )
        schema = self._profile.observed_structure.get("variable_schema", {})
        invalid = {
            "nan_count": sum(
                variable.nan_count
                for file in self._profile.files
                for variable in file.variables
            ),
            "inf_count": sum(
                variable.inf_count
                for file in self._profile.files
                for variable in file.variables
            ),
        }
        unknowns = self._bounded_list(
            self._profile.unknowns, self.limits.max_metadata_entries
        )
        value = {
            "profile_schema_version": self._profile.schema_version,
            "dataset_id": self._profile.dataset_id,
            "source_subsets": [self._profile.source.get("scope")]
            if self._profile.source.get("scope")
            else [],
            "run_count": len(self._profile.runs),
            "variables": variable_page,
            "file_formats": dict(
                self._profile.discovery.get("file_formats")
                or self._profile.discovery.get("matlab_formats", {})
            ),
            "sampling_rates_hz": rates,
            "sampling_rate_consistent": len(rates) <= 1 and len(rates) > 0,
            "sequence_lengths": lengths,
            "sequence_length_consistent": len(lengths) <= 1 and len(lengths) > 0,
            "variable_schema_consistent": all(
                len(observations) == 1 for observations in schema.values()
            ),
            "invalid_values": invalid,
            "quality_issue_counts": self._profile.quality.counts_by_severity,
            "unresolved_questions": unknowns,
        }
        return self._evidence(kind, "dataset_profile", "all_runs", None, value)

    def variable_schema(self, name: str) -> EvidenceResponse:
        kind = EvidenceKind.VARIABLE_SCHEMA
        if error := self._begin(kind):
            return error
        if error := self._validate_name(name, kind):
            return error
        schema = self._profile.observed_structure.get("variable_schema", {})
        if name not in schema:
            return self._error(
                EvidenceErrorCode.UNKNOWN_VARIABLE,
                kind,
                f"Variable {name!r} is not present in DatasetProfile.",
                variable=name,
            )
        summary = self._signal_summary(name)
        observations = schema[name]
        run_ids = sorted(
            {
                file.source_run_id
                for file in self._profile.files
                if any(variable.name == name for variable in file.variables)
            }
        )
        source_files = sorted(
            file.relative_path
            for file in self._profile.files
            if any(variable.name == name for variable in file.variables)
        )
        channel_counts = (
            [] if summary is None else summary.get("data_channel_count") or []
        )
        sequence_lengths = sorted(
            {
                run.sequence_length
                for run in self._profile.runs
                if run.sequence_length is not None
            }
        )
        logical_shape = None
        if len(channel_counts) == 1 and len(sequence_lengths) == 1:
            logical_shape = [sequence_lengths[0], channel_counts[0]]
        axis_sources = sorted(
            {
                run.metadata.get("time_axis_source")
                for run in self._profile.runs
                if run.metadata.get("time_axis_source")
            }
        )
        value = {
            "exists": True,
            "observed_shapes": [item.get("shape") for item in observations],
            "logical_shape": logical_shape,
            "dtypes": sorted({str(item.get("dtype")) for item in observations}),
            "ndim": sorted({int(item.get("ndim")) for item in observations}),
            "channel_counts": channel_counts,
            "sequence_lengths": sequence_lengths,
            "sampling_rates_hz": sorted(
                {
                    run.sampling_rate_hz
                    for run in self._profile.runs
                    if run.sampling_rate_hz is not None
                }
            ),
            "has_embedded_time_row": bool(
                summary and summary.get("has_embedded_time_row")
            ),
            "channel_axis": summary.get("channel_axis") if summary else None,
            "sample_axis": summary.get("sample_axis") if summary else None,
            "associated_time_axes": axis_sources,
            "profiler_semantic_hint": summary.get("inferred_semantic_name")
            if summary
            else None,
            "consistent_across_runs": len(observations) == 1,
            "run_coverage": self._bounded_list(
                run_ids, self.limits.max_metadata_entries
            ),
            "source_file_coverage": self._bounded_list(
                source_files, self.limits.max_metadata_entries
            ),
        }
        return self._evidence(kind, "dataset_profile", "all_runs", name, value)

    def signal_statistics(self, name: str) -> EvidenceResponse:
        kind = EvidenceKind.SIGNAL_STATISTICS
        if error := self._begin(kind):
            return error
        if error := self._validate_name(name, kind):
            return error
        variables = self._variables(name)
        if not variables:
            return self._error(
                EvidenceErrorCode.UNKNOWN_VARIABLE,
                kind,
                f"Variable {name!r} is not present in DatasetProfile.",
                variable=name,
            )
        summary = self._signal_summary(name)
        offset = 1 if summary and summary.get("has_embedded_time_row") else 0
        by_channel: dict[int, list[ChannelStats]] = {}
        for variable in variables:
            for stats in variable.channel_stats[offset:]:
                logical_index = stats.index - offset
                by_channel.setdefault(logical_index, []).append(stats)
        aggregated = [
            self._aggregate_channel(index, entries, offset)
            for index, entries in sorted(by_channel.items())
        ]
        returned = aggregated[: self.limits.max_statistics_entries]
        global_stats = self._aggregate_summaries(aggregated)
        value = {
            "dtype": sorted({variable.dtype for variable in variables}),
            "file_observations": len(variables),
            "global": global_stats,
            "per_channel": returned,
            "returned_channels": len(returned),
            "available_channels": len(aggregated),
            "truncated": len(returned) < len(aggregated),
        }
        if not aggregated:
            value["global"] = {
                "count": sum(variable.size for variable in variables),
                "minimum": _minimum(variable.minimum for variable in variables),
                "maximum": _maximum(variable.maximum for variable in variables),
                "mean": None,
                "standard_deviation": None,
                "nan_count": sum(variable.nan_count for variable in variables),
                "inf_count": sum(variable.inf_count for variable in variables),
            }
        return self._evidence(kind, "dataset_profile", "all_runs", name, value)

    def metadata_summary(self) -> EvidenceResponse:
        kind = EvidenceKind.METADATA_SUMMARY
        if error := self._begin(kind):
            return error
        run_ids = sorted(run.source_run_id for run in self._profile.runs)
        files = sorted(file.relative_path for file in self._profile.files)
        variables = sorted(self._profile.observed_structure.get("variable_schema", {}))
        events = [event for run in self._profile.runs for event in run.events]
        event_sources = sorted(
            item["observed_name"]
            for item in self._profile.signals
            if "event" in str(item.get("inferred_semantic_name", {}).get("value", ""))
        )
        indices = [event.observed_index for event in events]
        timestamps = [
            event.inferred_time_seconds
            for event in events
            if event.inferred_time_seconds is not None
        ]
        labels = sorted({str(event.interpretation.value) for event in events})
        value = {
            "source_subset": self._profile.source.get("scope"),
            "run_ids": self._bounded_list(run_ids, self.limits.max_metadata_entries),
            "source_files": self._bounded_list(files, self.limits.max_metadata_entries),
            "variable_names": self._bounded_list(
                variables, self.limits.max_metadata_entries
            ),
            "metadata_sources": self._bounded_list(
                sorted(self._profile.metadata.get("run_metadata_sources", [])),
                self.limits.max_metadata_entries,
            ),
            "dataset_specific_hints": self._profile.metadata.get(
                "dataset_specific_hints"
            ),
            "events": {
                "count": len(events),
                "source_variables": self._bounded_list(
                    event_sources, self.limits.max_metadata_entries
                ),
                "semantic_labels": self._bounded_list(
                    labels, self.limits.max_metadata_entries
                ),
                "observed_index_min": min(indices) if indices else None,
                "observed_index_max": max(indices) if indices else None,
                "timestamp_seconds_min": min(timestamps) if timestamps else None,
                "timestamp_seconds_max": max(timestamps) if timestamps else None,
                "sequence_length_bounds": sorted(
                    {
                        run.sequence_length
                        for run in self._profile.runs
                        if run.sequence_length is not None
                    }
                ),
            },
        }
        return self._evidence(kind, "dataset_profile", "all_runs", None, value)

    def bounded_excerpt(
        self,
        variable: str,
        run_id: str,
        *,
        start: int,
        length: int,
        channels: tuple[int, ...] | None = None,
    ) -> EvidenceResponse:
        kind = EvidenceKind.BOUNDED_EXCERPT
        if error := self._begin(kind):
            return error
        if error := self._validate_name(variable, kind):
            return error
        if variable not in self._profile.observed_structure.get("variable_schema", {}):
            return self._error(
                EvidenceErrorCode.UNKNOWN_VARIABLE,
                kind,
                f"Variable {variable!r} is not present in DatasetProfile.",
                variable=variable,
            )
        if not isinstance(run_id, str) or not run_id or len(run_id) > 200:
            return self._error(
                EvidenceErrorCode.INVALID_QUERY,
                kind,
                "run_id must be a non-empty string of at most 200 characters",
            )
        if run_id not in {run.source_run_id for run in self._profile.runs}:
            return self._error(
                EvidenceErrorCode.UNKNOWN_RUN,
                kind,
                f"Run {run_id!r} is not present in DatasetProfile.",
                run_id=run_id,
            )
        if (
            isinstance(start, bool)
            or isinstance(length, bool)
            or not isinstance(start, int)
            or not isinstance(length, int)
            or start < 0
            or length <= 0
        ):
            return self._error(
                EvidenceErrorCode.INVALID_QUERY,
                kind,
                "start must be non-negative and length must be a positive integer.",
            )
        if length > self.limits.max_excerpt_samples:
            return self._error(
                EvidenceErrorCode.EXCERPT_TOO_LARGE,
                kind,
                "Requested excerpt exceeds the per-query sample limit.",
                requested=length,
                limit=self.limits.max_excerpt_samples,
            )
        if channels is not None and (
            not channels
            or any(
                isinstance(channel, bool) or not isinstance(channel, int) or channel < 0
                for channel in channels
            )
        ):
            return self._error(
                EvidenceErrorCode.INVALID_QUERY,
                kind,
                "channels must contain non-negative integer channel indices.",
            )
        summary = self._signal_summary(variable)
        counts = summary.get("data_channel_count") if summary else None
        available_channels = counts[0] if counts and len(counts) == 1 else 1
        selected = tuple(range(available_channels)) if channels is None else channels
        if len(selected) > self.limits.max_excerpt_channels:
            return self._error(
                EvidenceErrorCode.CHANNEL_LIMIT_EXCEEDED,
                kind,
                "Requested excerpt exceeds the per-query channel limit.",
                requested=len(selected),
                limit=self.limits.max_excerpt_channels,
            )
        if len(set(selected)) != len(selected) or any(
            channel >= available_channels for channel in selected
        ):
            return self._error(
                EvidenceErrorCode.INVALID_QUERY,
                kind,
                "A requested channel is duplicated or outside the profiled range.",
                available_channels=available_channels,
            )
        value_count = length * len(selected)
        if error := self._check_excerpt_budget(value_count, kind):
            return error
        if not self._allow_excerpts:
            return self._error(
                EvidenceErrorCode.UNAVAILABLE_EVIDENCE,
                kind,
                "Bounded source excerpts were not enabled by the session host.",
            )
        try:
            values, dtype, available_samples = self._read_excerpt(
                variable, run_id, start, length, selected
            )
        except (OSError, ValueError):
            return self._error(
                EvidenceErrorCode.UNAVAILABLE_EVIDENCE,
                kind,
                "The bounded excerpt could not be produced from the profiled source.",
            )
        value = {
            "run_id": run_id,
            "variable": variable,
            "start": start,
            "length": length,
            "channels": list(selected),
            "dtype": dtype,
            "values": values,
            "returned_values": value_count,
            "available_samples": available_samples,
            "truncated": False,
        }
        result = self._evidence(
            kind,
            "bounded_profile_source",
            run_id,
            variable,
            value,
            query={
                "run_id": run_id,
                "start": start,
                "length": length,
                "channels": selected,
            },
        )
        if isinstance(result, Evidence):
            self._excerpt_queries += 1
            self._excerpt_values += value_count
        return result

    def _read_excerpt(
        self,
        variable: str,
        run_id: str,
        start: int,
        length: int,
        channels: tuple[int, ...],
    ) -> tuple[list[list[Any]], str, int]:
        matches = [
            file
            for file in self._profile.files
            if file.source_run_id == run_id
            and any(item.name == variable for item in file.variables)
        ]
        if len(matches) != 1:
            raise ValueError(
                f"expected one profiled source for {variable!r}, found {len(matches)}"
            )
        root_value = self._profile.source.get("path")
        if not isinstance(root_value, str) or not root_value:
            raise ValueError("profile has no trusted source root")
        root = Path(root_value).resolve()
        source = (root / matches[0].relative_path).resolve()
        try:
            source.relative_to(root)
        except ValueError as error:
            raise ValueError(
                "profiled source resolves outside the trusted dataset root"
            ) from error
        if not source.is_file() or sha256_file(source) != matches[0].sha256:
            raise ValueError(
                "profiled source is missing or has changed since profiling"
            )
        summary = self._signal_summary(variable)
        if source.suffix.casefold() in {".h5", ".hdf5"}:
            excerpt, dtype, available_samples = read_hdf5_excerpt(
                source,
                variable,
                start,
                length,
                channels,
                summary.get("channel_axis") if summary else None,
            )
            values = [[_json_scalar(value) for value in row] for row in excerpt]
            return values, dtype, available_samples
        raw = load_matlab(source).variables.get(variable)
        if not isinstance(raw, np.ndarray) or raw.ndim not in {1, 2}:
            raise ValueError("excerpt source is not a one- or two-dimensional array")
        if not np.issubdtype(raw.dtype, np.number):
            raise ValueError("excerpt source is not numeric")
        if raw.ndim == 1:
            array = raw.reshape(1, -1)
        elif summary and summary.get("channel_axis") == 1:
            array = raw.T
        else:
            array = raw
        if summary and summary.get("has_embedded_time_row"):
            array = array[1:]
        if start + length > array.shape[1]:
            raise ValueError(
                f"requested range ends at {start + length}, but only {array.shape[1]} samples exist"
            )
        excerpt = array[np.asarray(channels), start : start + length]
        values = [[_json_scalar(value) for value in row] for row in excerpt]
        return values, str(raw.dtype), int(array.shape[1])

    def _load_documentation(
        self,
        registrations: list[DocumentationSource] | tuple[DocumentationSource, ...],
    ) -> tuple[_LoadedDocumentation, ...]:
        indexed = list(enumerate(registrations))
        indexed.sort(
            key=lambda item: (
                item[1].source_id.casefold()
                if isinstance(item[1], DocumentationSource)
                and isinstance(item[1].source_id, str)
                else f"~invalid-{item[0]:08d}"
            )
        )
        selected = indexed[: self.limits.max_documentation_sources]
        loaded: list[_LoadedDocumentation] = []
        seen_ids: set[str] = set()
        for original_index, registration in selected:
            if not isinstance(registration, DocumentationSource):
                loaded.append(
                    _LoadedDocumentation(
                        f"invalid-{original_index + 1}",
                        f"Invalid source {original_index + 1}",
                        "unknown",
                        "invalid",
                        error_code=EvidenceErrorCode.INVALID_DOCUMENTATION_SOURCE,
                    )
                )
                continue
            source_id = registration.source_id
            display_name = registration.display_name or (
                Path(registration.path).name
                if isinstance(registration.path, (str, Path))
                else source_id
            )
            if (
                not isinstance(source_id, str)
                or not _SOURCE_ID_PATTERN.fullmatch(source_id)
                or source_id.casefold() in seen_ids
                or not isinstance(registration.path, (str, Path))
                or not isinstance(display_name, str)
                or not display_name.strip()
                or len(display_name) > 200
            ):
                loaded.append(
                    _LoadedDocumentation(
                        source_id
                        if isinstance(source_id, str) and source_id
                        else f"invalid-{original_index + 1}",
                        display_name
                        if isinstance(display_name, str) and display_name
                        else f"Invalid source {original_index + 1}",
                        "unknown",
                        "invalid",
                        error_code=EvidenceErrorCode.INVALID_DOCUMENTATION_SOURCE,
                    )
                )
                continue
            seen_ids.add(source_id.casefold())
            suffix = Path(registration.path).suffix.casefold()
            document_type = _DOCUMENTATION_SUFFIXES.get(
                suffix, suffix.removeprefix(".") or "unknown"
            )
            if suffix not in _DOCUMENTATION_SUFFIXES:
                loaded.append(
                    _LoadedDocumentation(
                        source_id,
                        display_name.strip(),
                        document_type,
                        "unsupported",
                        error_code=EvidenceErrorCode.UNSUPPORTED_DOCUMENTATION,
                    )
                )
                continue
            try:
                path = Path(registration.path).resolve(strict=True)
                if not path.is_file():
                    raise OSError("documentation source is not a regular file")
                size = path.stat().st_size
                if size > self.limits.max_document_bytes:
                    raise ValueError(
                        "documentation source exceeds the configured size limit"
                    )
                raw = path.read_bytes()
                text = raw.decode("utf-8")
                if "\x00" in text:
                    raise ValueError("documentation source contains NUL characters")
            except (OSError, RuntimeError, TypeError, UnicodeError, ValueError):
                loaded.append(
                    _LoadedDocumentation(
                        source_id,
                        display_name.strip(),
                        document_type,
                        "invalid",
                        error_code=EvidenceErrorCode.INVALID_DOCUMENTATION_SOURCE,
                    )
                )
                continue
            loaded.append(
                _LoadedDocumentation(
                    source_id,
                    display_name.strip(),
                    document_type,
                    "available",
                    size_bytes=len(raw),
                    line_count=len(text.splitlines()),
                    sha256=hashlib.sha256(raw).hexdigest(),
                    text=text,
                )
            )
        return tuple(loaded)

    @staticmethod
    def _documentation_match_rank(
        line: str,
        query: str,
        normalized_query: str,
        query_tokens: list[str],
    ) -> int | None:
        if query in line:
            return 0
        normalized_line = " ".join(line.casefold().split())
        if normalized_query in normalized_line:
            return 1
        line_tokens = set(re.findall(r"\w+", normalized_line))
        if query_tokens and all(token in line_tokens for token in query_tokens):
            return 2
        return None

    @staticmethod
    def _bounded_excerpt_text(
        excerpt: str,
        matching_line: str,
        query: str,
        limit: int,
    ) -> tuple[str, bool]:
        if len(excerpt) <= limit:
            return excerpt, False
        match_in_excerpt = excerpt.casefold().find(query.casefold())
        if match_in_excerpt < 0:
            match_in_excerpt = excerpt.find(matching_line)
        center = max(match_in_excerpt, 0) + min(len(query), limit) // 2
        start = max(0, center - limit // 2)
        end = min(len(excerpt), start + limit)
        start = max(0, end - limit)
        bounded = excerpt[start:end]
        if start:
            bounded = "…" + bounded[1:]
        if end < len(excerpt):
            bounded = bounded[:-1] + "…"
        return bounded, True

    def _validate_configuration(self) -> None:
        values = (*asdict(self.limits).values(), *asdict(self.budget).values())
        if any(
            isinstance(value, bool) or not isinstance(value, int) or value <= 0
            for value in values
        ):
            raise ValueError(
                "All evidence limits and budgets must be positive integers"
            )

    def _begin(self, kind: EvidenceKind) -> EvidenceError | None:
        if self._total_queries >= self.budget.max_total_queries:
            return self._error(
                EvidenceErrorCode.QUERY_BUDGET_EXCEEDED,
                kind,
                "The session's total evidence-query budget is exhausted.",
                limit=self.budget.max_total_queries,
                used=self._total_queries,
            )
        self._total_queries += 1
        return None

    def _check_excerpt_budget(
        self, value_count: int, kind: EvidenceKind
    ) -> EvidenceError | None:
        if self._excerpt_queries >= self.budget.max_excerpt_queries:
            return self._error(
                EvidenceErrorCode.EXCERPT_BUDGET_EXCEEDED,
                kind,
                "The session's excerpt-query budget is exhausted.",
                limit=self.budget.max_excerpt_queries,
                used=self._excerpt_queries,
            )
        if self._excerpt_values + value_count > self.budget.max_total_excerpt_values:
            return self._error(
                EvidenceErrorCode.SAMPLE_BUDGET_EXCEEDED,
                kind,
                "The session's total excerpt-value budget would be exceeded.",
                requested=value_count,
                used=self._excerpt_values,
                limit=self.budget.max_total_excerpt_values,
            )
        return None

    def _evidence(
        self,
        kind: EvidenceKind,
        source: str,
        scope: str,
        target: str | None,
        value: dict[str, Any],
        *,
        query: dict[str, Any] | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> EvidenceResponse:
        evidence_id = self._evidence_id(kind, target, query or {}, value)
        evidence_metadata = {"profile_fingerprint": self._profile_fingerprint}
        evidence_metadata.update(metadata or {})
        item = Evidence(
            evidence_id, kind, source, scope, target, value, evidence_metadata
        )
        size = len(item.to_json(indent=None).encode())
        if size > self.limits.max_response_bytes:
            return self._error(
                EvidenceErrorCode.RESPONSE_TOO_LARGE,
                kind,
                "Evidence response exceeds the configured serialized-size limit.",
                response_bytes=size,
                limit=self.limits.max_response_bytes,
            )
        return item

    def _evidence_id(
        self,
        kind: EvidenceKind,
        target: str | None,
        query: dict[str, Any],
        value: dict[str, Any],
    ) -> str:
        identity = json.dumps(
            {
                "profile": self._profile_fingerprint,
                "kind": kind,
                "target": target,
                "query": query,
                "value": value,
            },
            sort_keys=True,
            separators=(",", ":"),
        )
        suffix = hashlib.sha256(identity.encode()).hexdigest()[:12]
        target_slug = re.sub(
            r"[^a-z0-9]+", "_", (target or "dataset").casefold()
        ).strip("_")
        return f"ev_{kind.value}_{target_slug}_{suffix}"

    def _error(
        self, code: EvidenceErrorCode, query: EvidenceKind, message: str, **details: Any
    ) -> EvidenceError:
        return EvidenceError(code, query, message, details)

    def _validate_name(self, name: str, kind: EvidenceKind) -> EvidenceError | None:
        if not isinstance(name, str) or not name or len(name) > 200:
            return self._error(
                EvidenceErrorCode.INVALID_QUERY,
                kind,
                "variable must be a non-empty string of at most 200 characters",
            )
        return None

    def _variables(self, name: str) -> list[VariableProfile]:
        return [
            variable
            for file in self._profile.files
            for variable in file.variables
            if variable.name == name
        ]

    def _signal_summary(self, name: str) -> dict[str, Any] | None:
        return next(
            (
                item
                for item in self._profile.signals
                if item.get("observed_name") == name
            ),
            None,
        )

    @staticmethod
    def _bounded_list(values: list[Any], limit: int) -> dict[str, Any]:
        returned = values[:limit]
        return {
            "items": returned,
            "returned": len(returned),
            "available": len(values),
            "truncated": len(returned) < len(values),
        }

    @staticmethod
    def _aggregate_channel(
        index: int, entries: list[ChannelStats], source_offset: int
    ) -> dict[str, Any]:
        finite_count = sum(
            item.count - item.nan_count - item.inf_count for item in entries
        )
        weighted_sum = sum(
            (item.mean or 0.0) * (item.count - item.nan_count - item.inf_count)
            for item in entries
        )
        second_moment_sum = sum(
            ((item.standard_deviation or 0.0) ** 2 + (item.mean or 0.0) ** 2)
            * (item.count - item.nan_count - item.inf_count)
            for item in entries
        )
        mean = weighted_sum / finite_count if finite_count else None
        variance = (
            max(second_moment_sum / finite_count - mean**2, 0.0)
            if finite_count and mean is not None
            else None
        )
        return {
            "channel_index": index,
            "source_index": index + source_offset,
            "count": sum(item.count for item in entries),
            "minimum": _minimum(item.minimum for item in entries),
            "maximum": _maximum(item.maximum for item in entries),
            "mean": mean,
            "standard_deviation": math.sqrt(variance) if variance is not None else None,
            "nan_count": sum(item.nan_count for item in entries),
            "inf_count": sum(item.inf_count for item in entries),
        }

    @staticmethod
    def _aggregate_summaries(entries: list[dict[str, Any]]) -> dict[str, Any]:
        finite_count = sum(
            item["count"] - item["nan_count"] - item["inf_count"] for item in entries
        )
        weighted_sum = sum(
            (item["mean"] or 0.0)
            * (item["count"] - item["nan_count"] - item["inf_count"])
            for item in entries
        )
        second_moment_sum = sum(
            ((item["standard_deviation"] or 0.0) ** 2 + (item["mean"] or 0.0) ** 2)
            * (item["count"] - item["nan_count"] - item["inf_count"])
            for item in entries
        )
        mean = weighted_sum / finite_count if finite_count else None
        variance = (
            max(second_moment_sum / finite_count - mean**2, 0.0)
            if finite_count and mean is not None
            else None
        )
        return {
            "count": sum(item["count"] for item in entries),
            "minimum": _minimum(item["minimum"] for item in entries),
            "maximum": _maximum(item["maximum"] for item in entries),
            "mean": mean,
            "standard_deviation": math.sqrt(variance) if variance is not None else None,
            "nan_count": sum(item["nan_count"] for item in entries),
            "inf_count": sum(item["inf_count"] for item in entries),
        }


def _minimum(values: Any) -> float | None:
    finite = [value for value in values if value is not None]
    return min(finite) if finite else None


def _maximum(values: Any) -> float | None:
    finite = [value for value in values if value is not None]
    return max(finite) if finite else None


def _json_scalar(value: Any) -> Any:
    scalar = value.item() if isinstance(value, np.generic) else value
    if isinstance(scalar, complex):
        return {"real": scalar.real, "imag": scalar.imag}
    if isinstance(scalar, float) and not math.isfinite(scalar):
        return (
            "NaN" if math.isnan(scalar) else ("Infinity" if scalar > 0 else "-Infinity")
        )
    return scalar

from __future__ import annotations

from collections import Counter, defaultdict
from pathlib import Path
import hashlib
import json
from typing import Any

import numpy as np

from .audit import audit_profile_inputs
from .datasets import KukaCollisionHints
from .inspection import inspect_mat_file
from .io.hdf5 import inspect_hdf5_file, inspect_hdf5_structure
from .io.matlab import load_matlab
from .models import DatasetProfile, RunProfile


def discover_runs(root: str | Path) -> list[Path]:
    source = Path(root).resolve()
    if list(source.glob("*.mat")):
        return [source]
    return sorted(
        directory
        for directory in source.iterdir()
        if directory.is_dir() and any(directory.glob("*.mat"))
    )


def _discover_hdf5_files(root: Path) -> list[Path]:
    return sorted((*root.rglob("*.h5"), *root.rglob("*.hdf5")))


def _stable_run_id(dataset_id: str, source_run_id: str) -> str:
    suffix = hashlib.sha256(f"{dataset_id}\0{source_run_id}".encode()).hexdigest()[:12]
    return f"{dataset_id}:{source_run_id}:{suffix}"


def _find_time_axis(run_dir: Path) -> tuple[np.ndarray | None, str | None]:
    candidates = [(run_dir / "JsmoExp.mat", "rt_tout")]
    candidates.extend((path, "") for path in sorted(run_dir.glob("*.mat")))
    for path, preferred in candidates:
        if not path.exists():
            continue
        for name, value in load_matlab(path).variables.items():
            array = np.asarray(value)
            if preferred and name != preferred:
                continue
            flat = array.reshape(-1)
            if flat.size >= 2 and np.issubdtype(flat.dtype, np.number):
                differences = np.diff(flat)
                if np.all(np.isfinite(flat)) and np.all(differences > 0):
                    return flat, f"{path.name}:{name}"
        if preferred:
            continue
    return None, None


def _run_profile(
    dataset_id: str, root: Path, run_dir: Path, hints: Any | None
) -> RunProfile:
    source_run_id = (
        run_dir.relative_to(root).as_posix() if run_dir != root else run_dir.name
    )
    time_axis, time_source = _find_time_axis(run_dir)
    rate = None
    monotonic = None
    if time_axis is not None:
        differences = np.diff(time_axis)
        monotonic = bool(np.all(differences > 0))
        if monotonic:
            rate = float(1.0 / np.median(differences))
            if np.isclose(rate, round(rate), rtol=1e-9, atol=1e-9):
                rate = float(round(rate))
    metadata = hints.parse_run_metadata(run_dir) if hints else {}
    if time_source:
        metadata["time_axis_source"] = time_source
    events = hints.events(run_dir, time_axis) if hints else []
    if events and metadata.get("collision_times") is not None:
        metadata["event_count_matches_readme"] = len(events) == len(
            metadata["collision_times"]
        )
        start = metadata.get("start_time")
        if start and len(events) == len(metadata["collision_times"]):

            def seconds(value: str) -> int:
                hours, minutes, secs = map(int, value.split(":"))
                return hours * 3600 + minutes * 60 + secs

            start_seconds = seconds(start)
            offsets = [
                (seconds(value) - start_seconds) % 86400
                for value in metadata["collision_times"]
            ]
            errors = [
                abs(offset - event.inferred_time_seconds)
                for offset, event in zip(offsets, events)
                if event.inferred_time_seconds is not None
            ]
            metadata["event_time_alignment_max_abs_seconds"] = (
                max(errors) if errors else None
            )
    return RunProfile(
        internal_id=_stable_run_id(dataset_id, source_run_id),
        dataset_id=dataset_id,
        source_run_id=source_run_id,
        original_sequence_id=run_dir.name,
        source_directory=source_run_id,
        source_files=sorted(
            path.relative_to(root).as_posix()
            for path in run_dir.iterdir()
            if path.is_file()
        ),
        sequence_length=int(time_axis.size) if time_axis is not None else None,
        channel_counts={},
        sampling_rate_hz=rate,
        time_start=float(time_axis[0]) if time_axis is not None else None,
        time_end=float(time_axis[-1]) if time_axis is not None else None,
        timestamps_monotonic=monotonic,
        metadata=metadata,
        events=events,
    )


def _signal_summary(files: list[Any], hints: Any | None) -> list[dict[str, Any]]:
    observations: dict[str, list[tuple[str, Any]]] = defaultdict(list)
    for file in files:
        for variable in file.variables:
            observations[variable.name].append((file.source_run_id, variable))
    summaries: list[dict[str, Any]] = []
    names = hints.signal_names if hints else {}
    for name, items in sorted(observations.items()):
        shapes = sorted({tuple(variable.shape) for _, variable in items})
        dtypes = sorted({variable.dtype for _, variable in items})
        matrix = all(variable.ndim == 2 for _, variable in items)
        has_embedded_time = (
            matrix
            and all(
                variable.shape[0] > 1 and variable.shape[1] > variable.shape[0]
                for _, variable in items
            )
            and name not in {"JK_moments"}
        )
        structural_axes = [
            variable.nested_structure.get("structural_axes", {})
            for _, variable in items
            if isinstance(variable.nested_structure, dict)
        ]
        channel_axes = {axes.get("channel_axis") for axes in structural_axes}
        sample_axes = {axes.get("sample_axis") for axes in structural_axes}
        channel_axes.discard(None)
        sample_axes.discard(None)
        channel_axis = (
            next(iter(channel_axes))
            if len(channel_axes) == 1
            else (0 if has_embedded_time else None)
        )
        sample_axis = (
            next(iter(sample_axes))
            if len(sample_axes) == 1
            else (1 if has_embedded_time else None)
        )
        if has_embedded_time:
            data_channel_count = sorted({v.shape[0] - 1 for _, v in items})
        elif channel_axis is not None:
            data_channel_count = sorted({v.shape[channel_axis] for _, v in items})
        else:
            data_channel_count = None
        summaries.append(
            {
                "observed_name": name,
                "observed_shapes": [list(shape) for shape in shapes],
                "observed_dtypes": dtypes,
                "files_count": len(items),
                "has_embedded_time_row": has_embedded_time,
                "data_channel_count": data_channel_count,
                "channel_axis": channel_axis,
                "sample_axis": sample_axis,
                "inferred_semantic_name": {
                    "value": names.get(name, "unknown"),
                    "confidence": 0.98 if name in names else 0.0,
                    "evidence": ["dataset-specific KUKA hint mapping"]
                    if name in names
                    else [],
                },
            }
        )
    return summaries


def profile_dataset(
    source: str | Path,
    dataset_id: str,
    *,
    hints: Any | None = None,
) -> DatasetProfile:
    root = Path(source).resolve()
    if not root.is_dir():
        raise ValueError(f"Dataset source is not a directory: {root}")
    hdf5_files = _discover_hdf5_files(root)
    run_dirs = discover_runs(root)
    if hdf5_files and run_dirs:
        raise ValueError("Mixed MAT and HDF5 dataset roots are not supported")
    if not run_dirs and not hdf5_files:
        raise ValueError(f"No supported MAT or HDF5 files found under {root}")

    hierarchy_variants: dict[str, dict[str, Any]] = {}
    if hdf5_files:
        runs, files = _profile_hdf5(root, dataset_id, hdf5_files, hierarchy_variants)
    else:
        runs = [_run_profile(dataset_id, root, run_dir, hints) for run_dir in run_dirs]
        files = _profile_mat_files(root, run_dirs, runs)

    format_counts = Counter(file.format for file in files)
    variable_schema: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for file in files:
        for variable in file.variables:
            observation = {
                "shape": variable.shape,
                "dtype": variable.dtype,
                "ndim": variable.ndim,
            }
            if observation not in variable_schema[variable.name]:
                variable_schema[variable.name].append(observation)
    audit = audit_profile_inputs(files, runs)
    semantics = hints.semantic_claims() if hints else []
    unknowns = (
        hints.unknowns()
        if hints
        else [
            "Signal semantics, units, sampling/time interpretation, and directory metadata "
            "meanings have not been identified."
        ]
    )
    return DatasetProfile(
        schema_version="1.0.0",
        dataset_id=dataset_id,
        source={
            "path": str(root),
            "scope": "Part I Batch 01"
            if isinstance(hints, KukaCollisionHints)
            else "user-provided directory",
            "raw_data_copied": False,
        },
        discovery={
            "run_directories": (
                len(run_dirs)
                if not hdf5_files
                else len({path.parent for path in hdf5_files})
            ),
            "mat_files": len(files) if not hdf5_files else 0,
            "hdf5_files": len(files) if hdf5_files else 0,
            "all_files": sum(len(run.source_files) for run in runs),
            "matlab_formats": dict(sorted(format_counts.items()))
            if not hdf5_files
            else {},
            "file_formats": dict(sorted(format_counts.items())),
            "compression_layout": "already extracted; no archive found inside source directory",
        },
        files=files,
        runs=runs,
        observed_structure={
            "record_boundary": "HDF5 file"
            if hdf5_files
            else "directory containing MAT files",
            "variable_schema": dict(sorted(variable_schema.items())),
            "sequence_lengths": [run.sequence_length for run in runs],
            "sampling_rates_hz": [run.sampling_rate_hz for run in runs],
            "hdf5_hierarchy_variants": list(hierarchy_variants.values()),
        },
        signals=_signal_summary(files, hints),
        entities=[
            {
                "entity_type": "experimental_run",
                "count": len(runs),
                "identifier_fields": [
                    "dataset_id",
                    "source_run_id",
                    "original_sequence_id",
                    "internal_id",
                ],
                "future_window_provenance_fields": [
                    "source_run_id",
                    "window_start",
                    "window_end",
                ],
            }
        ],
        metadata={
            "run_metadata_sources": sorted(
                {
                    run.metadata.get("metadata_source")
                    for run in runs
                    if run.metadata.get("metadata_source")
                }
            ),
            "dataset_specific_hints": type(hints).__name__ if hints else None,
        },
        quality=audit,
        inferred_semantics=semantics,
        unknowns=unknowns,
    )


def _profile_mat_files(
    root: Path, run_dirs: list[Path], runs: list[RunProfile]
) -> list[Any]:
    by_source_id = {run.source_run_id: run for run in runs}
    files = []
    for run_dir in run_dirs:
        source_run_id = (
            run_dir.relative_to(root).as_posix() if run_dir != root else run_dir.name
        )
        for path in sorted(run_dir.glob("*.mat")):
            profile = inspect_mat_file(path, root, source_run_id)
            files.append(profile)
            for variable in profile.variables:
                likely_time_row = (
                    variable.ndim == 2
                    and len(variable.shape) == 2
                    and variable.shape[0] > 1
                    and variable.shape[1] > variable.shape[0]
                    and variable.name != "JK_moments"
                )
                if likely_time_row:
                    by_source_id[source_run_id].channel_counts[variable.name] = (
                        variable.shape[0] - 1
                    )
    return files


def _profile_hdf5(
    root: Path,
    dataset_id: str,
    paths: list[Path],
    hierarchy_variants: dict[str, dict[str, Any]],
) -> tuple[list[RunProfile], list[Any]]:
    runs: list[RunProfile] = []
    files = []
    for path in paths:
        source_run_id = path.relative_to(root).as_posix()
        profile = inspect_hdf5_file(path, root, source_run_id)
        files.append(profile)
        sample_lengths = {
            variable.shape[axes["sample_axis"]]
            for variable in profile.variables
            if isinstance(variable.nested_structure, dict)
            and (axes := variable.nested_structure.get("structural_axes", {})).get(
                "sample_axis"
            )
            is not None
        }
        channel_counts = {
            variable.name: variable.shape[axes["channel_axis"]]
            for variable in profile.variables
            if isinstance(variable.nested_structure, dict)
            and (axes := variable.nested_structure.get("structural_axes", {})).get(
                "channel_axis"
            )
            is not None
        }
        runs.append(
            RunProfile(
                internal_id=_stable_run_id(dataset_id, source_run_id),
                dataset_id=dataset_id,
                source_run_id=source_run_id,
                original_sequence_id=path.relative_to(root).with_suffix("").as_posix(),
                source_directory=path.parent.relative_to(root).as_posix(),
                source_files=[source_run_id],
                sequence_length=next(iter(sample_lengths))
                if len(sample_lengths) == 1
                else None,
                channel_counts=channel_counts,
                sampling_rate_hz=None,
                time_start=None,
                time_end=None,
                timestamps_monotonic=None,
                metadata={
                    "source_parent_parts": list(path.parent.relative_to(root).parts)
                },
                events=[],
            )
        )
        structure = inspect_hdf5_structure(path)
        structure_value = {
            "root_attributes": structure.root_attributes,
            "groups": list(structure.groups),
            "datasets": sorted(variable.name for variable in profile.variables),
        }
        signature = json.dumps(structure_value, sort_keys=True)
        variant = hierarchy_variants.setdefault(
            signature, {**structure_value, "files": []}
        )
        variant["files"].append(source_run_id)
    return runs, files

from __future__ import annotations

from collections import Counter, defaultdict
from pathlib import Path
import hashlib
from typing import Any

import numpy as np

from .audit import audit_profile_inputs
from .datasets import KukaCollisionHints
from .inspection import inspect_mat_file
from .io.matlab import load_matlab
from .models import DatasetProfile, RunProfile


def discover_runs(root: str | Path) -> list[Path]:
    source = Path(root).resolve()
    if list(source.glob("*.mat")):
        return [source]
    return sorted(
        directory
        for directory in source.iterdir()
        if directory.is_dir() and any(directory.glob("*.mat"))
    )


def _stable_run_id(dataset_id: str, source_run_id: str) -> str:
    suffix = hashlib.sha256(f"{dataset_id}\0{source_run_id}".encode()).hexdigest()[:12]
    return f"{dataset_id}:{source_run_id}:{suffix}"


def _find_time_axis(run_dir: Path) -> tuple[np.ndarray | None, str | None]:
    candidates = [(run_dir / "JsmoExp.mat", "rt_tout")]
    candidates.extend((path, "") for path in sorted(run_dir.glob("*.mat")))
    for path, preferred in candidates:
        if not path.exists():
            continue
        for name, value in load_matlab(path).variables.items():
            array = np.asarray(value)
            if preferred and name != preferred:
                continue
            flat = array.reshape(-1)
            if flat.size >= 2 and np.issubdtype(flat.dtype, np.number):
                differences = np.diff(flat)
                if np.all(np.isfinite(flat)) and np.all(differences > 0):
                    return flat, f"{path.name}:{name}"
        if preferred:
            continue
    return None, None


def _run_profile(dataset_id: str, root: Path, run_dir: Path, hints: Any | None) -> RunProfile:
    source_run_id = run_dir.relative_to(root).as_posix() if run_dir != root else run_dir.name
    time_axis, time_source = _find_time_axis(run_dir)
    rate = None
    monotonic = None
    if time_axis is not None:
        differences = np.diff(time_axis)
        monotonic = bool(np.all(differences > 0))
        if monotonic:
            rate = float(1.0 / np.median(differences))
            if np.isclose(rate, round(rate), rtol=1e-9, atol=1e-9):
                rate = float(round(rate))
    metadata = hints.parse_run_metadata(run_dir) if hints else {}
    if time_source:
        metadata["time_axis_source"] = time_source
    events = hints.events(run_dir, time_axis) if hints else []
    if events and metadata.get("collision_times") is not None:
        metadata["event_count_matches_readme"] = len(events) == len(metadata["collision_times"])
        start = metadata.get("start_time")
        if start and len(events) == len(metadata["collision_times"]):
            def seconds(value: str) -> int:
                hours, minutes, secs = map(int, value.split(":"))
                return hours * 3600 + minutes * 60 + secs

            start_seconds = seconds(start)
            offsets = [(seconds(value) - start_seconds) % 86400 for value in metadata["collision_times"]]
            errors = [abs(offset - event.inferred_time_seconds) for offset, event in zip(offsets, events) if event.inferred_time_seconds is not None]
            metadata["event_time_alignment_max_abs_seconds"] = max(errors) if errors else None
    return RunProfile(
        internal_id=_stable_run_id(dataset_id, source_run_id),
        dataset_id=dataset_id,
        source_run_id=source_run_id,
        original_sequence_id=run_dir.name,
        source_directory=source_run_id,
        source_files=sorted(path.relative_to(root).as_posix() for path in run_dir.iterdir() if path.is_file()),
        sequence_length=int(time_axis.size) if time_axis is not None else None,
        channel_counts={},
        sampling_rate_hz=rate,
        time_start=float(time_axis[0]) if time_axis is not None else None,
        time_end=float(time_axis[-1]) if time_axis is not None else None,
        timestamps_monotonic=monotonic,
        metadata=metadata,
        events=events,
    )


def _signal_summary(files: list[Any], hints: Any | None) -> list[dict[str, Any]]:
    observations: dict[str, list[tuple[str, Any]]] = defaultdict(list)
    for file in files:
        for variable in file.variables:
            observations[variable.name].append((file.source_run_id, variable))
    summaries: list[dict[str, Any]] = []
    names = hints.signal_names if hints else {}
    for name, items in sorted(observations.items()):
        shapes = sorted({tuple(variable.shape) for _, variable in items})
        dtypes = sorted({variable.dtype for _, variable in items})
        matrix = all(variable.ndim == 2 for _, variable in items)
        has_embedded_time = matrix and all(
            variable.shape[0] > 1 and variable.shape[1] > variable.shape[0]
            for _, variable in items
        ) and name not in {"JK_moments"}
        summaries.append(
            {
                "observed_name": name,
                "observed_shapes": [list(shape) for shape in shapes],
                "observed_dtypes": dtypes,
                "files_count": len(items),
                "has_embedded_time_row": has_embedded_time,
                "data_channel_count": sorted({v.shape[0] - 1 for _, v in items}) if has_embedded_time else None,
                "inferred_semantic_name": {
                    "value": names.get(name, "unknown"),
                    "confidence": 0.98 if name in names else 0.0,
                    "evidence": ["dataset-specific KUKA hint mapping"] if name in names else [],
                },
            }
        )
    return summaries


def profile_dataset(
    source: str | Path,
    dataset_id: str,
    *,
    hints: Any | None = None,
) -> DatasetProfile:
    root = Path(source).resolve()
    if not root.is_dir():
        raise ValueError(f"Dataset source is not a directory: {root}")
    run_dirs = discover_runs(root)
    if not run_dirs:
        raise ValueError(f"No directories containing MAT files found under {root}")

    runs = [_run_profile(dataset_id, root, run_dir, hints) for run_dir in run_dirs]
    by_source_id = {run.source_run_id: run for run in runs}
    files = []
    for run_dir in run_dirs:
        source_run_id = run_dir.relative_to(root).as_posix() if run_dir != root else run_dir.name
        for path in sorted(run_dir.glob("*.mat")):
            profile = inspect_mat_file(path, root, source_run_id)
            files.append(profile)
            for variable in profile.variables:
                likely_time_row = (
                    variable.ndim == 2
                    and len(variable.shape) == 2
                    and variable.shape[0] > 1
                    and variable.shape[1] > variable.shape[0]
                    and variable.name != "JK_moments"
                )
                if likely_time_row:
                    by_source_id[source_run_id].channel_counts[variable.name] = variable.shape[0] - 1

    format_counts = Counter(file.format for file in files)
    variable_schema: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for file in files:
        for variable in file.variables:
            observation = {"shape": variable.shape, "dtype": variable.dtype, "ndim": variable.ndim}
            if observation not in variable_schema[variable.name]:
                variable_schema[variable.name].append(observation)
    audit = audit_profile_inputs(files, runs)
    semantics = hints.semantic_claims() if hints else []
    unknowns = hints.unknowns() if hints else ["Signal semantics and record boundaries have not been identified."]
    return DatasetProfile(
        schema_version="1.0.0",
        dataset_id=dataset_id,
        source={
            "path": str(root),
            "scope": "Part I Batch 01" if isinstance(hints, KukaCollisionHints) else "user-provided directory",
            "raw_data_copied": False,
        },
        discovery={
            "run_directories": len(run_dirs),
            "mat_files": len(files),
            "all_files": sum(len(run.source_files) for run in runs),
            "matlab_formats": dict(sorted(format_counts.items())),
            "compression_layout": "already extracted; no archive found inside source directory",
        },
        files=files,
        runs=runs,
        observed_structure={
            "record_boundary": "directory containing MAT files",
            "variable_schema": dict(sorted(variable_schema.items())),
            "sequence_lengths": [run.sequence_length for run in runs],
            "sampling_rates_hz": [run.sampling_rate_hz for run in runs],
        },
        signals=_signal_summary(files, hints),
        entities=[
            {
                "entity_type": "experimental_run",
                "count": len(runs),
                "identifier_fields": ["dataset_id", "source_run_id", "original_sequence_id", "internal_id"],
                "future_window_provenance_fields": ["source_run_id", "window_start", "window_end"],
            }
        ],
        metadata={
            "run_metadata_sources": sorted({run.metadata.get("metadata_source") for run in runs if run.metadata.get("metadata_source")}),
            "dataset_specific_hints": type(hints).__name__ if hints else None,
        },
        quality=audit,
        inferred_semantics=semantics,
        unknowns=unknowns,
    )

"""Deterministic validation of semantic DatasetSpecs against DatasetProfiles."""

from __future__ import annotations

from dataclasses import asdict, dataclass, field
import json
from math import isclose
import re
from typing import Any

from ..models import DatasetProfile
from .models import (
    DatasetSpec,
    EvidenceClaim,
    EvidenceStatus,
    IndexBase,
    IndexConversion,
    VariableRole,
)


@dataclass(frozen=True)
class ValidationIssue:
    code: str
    path: str
    message: str
    details: dict[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class ValidationResult:
    valid: bool
    errors: tuple[ValidationIssue, ...]

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    def to_json(self, *, indent: int = 2) -> str:
        return json.dumps(self.to_dict(), indent=indent, allow_nan=False) + "\n"


def validate_dataset_spec(
    profile: DatasetProfile, spec: DatasetSpec
) -> ValidationResult:
    """Return repair-oriented issues instead of raising for ordinary validation failures."""
    issues: list[ValidationIssue] = []

    def add(code: str, path: str, message: str, **details: Any) -> None:
        issues.append(ValidationIssue(code, path, message, details))

    accepted_ids = {spec.identity.dataset_id, *spec.identity.compatible_profile_ids}
    if profile.dataset_id not in accepted_ids:
        add(
            "DATASET_ID_MISMATCH",
            "identity.dataset_id",
            f"Profile dataset_id {profile.dataset_id!r} is not declared by the spec.",
            observed=profile.dataset_id,
            accepted=sorted(accepted_ids),
        )

    observed_boundary = profile.observed_structure.get("record_boundary")
    if observed_boundary != spec.record_discovery.boundary:
        add(
            "RECORD_BOUNDARY_MISMATCH",
            "record_discovery.boundary",
            "Record-discovery boundary does not match the profiled structure.",
            claimed=spec.record_discovery.boundary,
            observed=observed_boundary,
        )
    observed_subset = profile.source.get("scope")
    normalized_subsets = {
        _normalized_text(value) for value in spec.identity.source_subsets
    }
    if (
        observed_subset
        and _normalized_text(str(observed_subset)) not in normalized_subsets
    ):
        add(
            "SOURCE_SUBSET_MISMATCH",
            "identity.source_subsets",
            f"Profile source scope {observed_subset!r} is not declared by the spec.",
            observed=observed_subset,
        )

    observed_schema = profile.observed_structure.get("variable_schema", {})
    summaries = {item.get("observed_name"): item for item in profile.signals}
    declared = {item.name: item for item in spec.source_variables}
    for index, variable in enumerate(spec.source_variables):
        if variable.name not in observed_schema:
            add(
                "UNKNOWN_SOURCE_VARIABLE",
                f"source_variables[{index}].name",
                f"Variable {variable.name!r} does not exist in DatasetProfile.",
                source_variable=variable.name,
            )

    observed_runs = {run.source_run_id for run in profile.runs}
    for index, run_id in enumerate(spec.record_discovery.included_run_ids):
        if run_id not in observed_runs:
            add(
                "UNKNOWN_RUN_REFERENCE",
                f"record_discovery.included_run_ids[{index}]",
                f"Run {run_id!r} does not exist in DatasetProfile.",
                source_run_id=run_id,
            )

    axes = {axis.name: axis for axis in spec.time_axes}
    for index, axis in enumerate(spec.time_axes):
        path = f"time_axes[{index}]"
        _check_reference(
            axis.source_variable,
            VariableRole.TIME,
            f"{path}.source_variable",
            declared,
            add,
        )
        if axis.source_variable not in observed_schema:
            add(
                "TIME_AXIS_NOT_OBSERVED",
                f"{path}.source_variable",
                f"Time variable {axis.source_variable!r} was not observed.",
            )
        if axis.monotonic and any(
            run.timestamps_monotonic is not True for run in profile.runs
        ):
            add(
                "TIME_AXIS_NOT_MONOTONIC",
                f"{path}.monotonic",
                "The spec requires a monotonic time axis, but not every run verifies it.",
            )

    run_rates = [run.sampling_rate_hz for run in profile.runs]
    sequence_lengths = {
        run.sequence_length for run in profile.runs if run.sequence_length is not None
    }
    for index, signal in enumerate(spec.signals):
        path = f"signals[{index}]"
        _check_reference(
            signal.source_variable,
            VariableRole.SIGNAL,
            f"{path}.source_variable",
            declared,
            add,
        )
        summary = summaries.get(signal.source_variable)
        if summary is None:
            continue
        observed_counts = summary.get("data_channel_count")
        if not observed_counts or set(observed_counts) != {signal.channels.count}:
            add(
                "CHANNEL_COUNT_MISMATCH",
                f"{path}.channels.count",
                f"Claimed {signal.channels.count} channels do not match observed {observed_counts}.",
                claimed=signal.channels.count,
                observed=observed_counts,
            )
        if (
            len(signal.channels.source_indices) != signal.channels.count
            or len(signal.channels.target_names) != signal.channels.count
        ):
            add(
                "CHANNEL_MAPPING_COUNT_MISMATCH",
                f"{path}.channels",
                "Channel count, source indices, and target names must have equal lengths.",
            )
        shapes = summary.get("observed_shapes", [])
        channel_axis = summary.get("channel_axis", 0)
        row_counts = {
            shape[channel_axis]
            for shape in shapes
            if shape and channel_axis is not None and channel_axis < len(shape)
        }
        source_indices = signal.channels.source_indices
        if len(set(source_indices)) != len(source_indices) or any(
            index < 0 or any(index >= rows for rows in row_counts)
            for index in source_indices
        ):
            add(
                "INVALID_CHANNEL_MAPPING",
                f"{path}.channels.source_indices",
                "Source channel indices must be unique and within every observed matrix shape.",
                source_indices=source_indices,
                observed_row_counts=sorted(row_counts),
            )
        observed_dtypes = summary.get("observed_dtypes", [])
        if signal.dtype not in observed_dtypes:
            add(
                "DTYPE_MISMATCH",
                f"{path}.dtype",
                f"Claimed dtype {signal.dtype!r} is not among observed dtypes {observed_dtypes!r}.",
            )
        if signal.sampling.time_axis not in axes:
            add(
                "UNKNOWN_TIME_AXIS",
                f"{path}.sampling.time_axis",
                f"Time axis {signal.sampling.time_axis!r} is not declared.",
            )
        if signal.sampling.rate_hz is not None:
            bad_rates = [
                rate
                for rate in run_rates
                if rate is None
                or not isclose(
                    rate, signal.sampling.rate_hz, rel_tol=1e-9, abs_tol=1e-9
                )
            ]
            if bad_rates:
                add(
                    "SAMPLING_RATE_MISMATCH",
                    f"{path}.sampling.rate_hz",
                    f"Claimed {signal.sampling.rate_hz} Hz does not match every run.",
                    claimed=signal.sampling.rate_hz,
                    observed=run_rates,
                )
        sample_axis = summary.get("sample_axis", -1)
        signal_lengths = {
            shape[sample_axis]
            for shape in shapes
            if shape and sample_axis is not None and abs(sample_axis) < len(shape)
        }
        if sequence_lengths and signal_lengths != sequence_lengths:
            add(
                "SEQUENCE_LENGTH_MISMATCH",
                f"{path}.source_variable",
                "Signal sample dimensions do not match profiled run sequence lengths.",
                signal_lengths=sorted(signal_lengths),
                run_lengths=sorted(sequence_lengths),
            )
        _check_claim(signal.unit.resolution, f"{path}.unit.resolution", add)
        if signal.unit.resolution.status is EvidenceStatus.UNRESOLVED:
            if signal.unit.name is not None or signal.unit.symbol is not None:
                add(
                    "INVALID_UNIT_CLAIM",
                    f"{path}.unit",
                    "Unresolved units must use null name and symbol fields.",
                )
        elif not signal.unit.name or not signal.unit.symbol:
            add(
                "INVALID_UNIT_CLAIM",
                f"{path}.unit",
                "Resolved unit information requires non-empty name and symbol fields.",
            )
        if signal.unit.resolution.status is EvidenceStatus.OBSERVED:
            observed_unit = summary.get("observed_unit")
            if observed_unit is None:
                add(
                    "UNIT_NOT_OBSERVED",
                    f"{path}.unit.resolution.status",
                    "The spec calls this unit observed, but DatasetProfile contains no observed unit.",
                )
            else:
                observed_name = (
                    observed_unit.get("name")
                    if isinstance(observed_unit, dict)
                    else str(observed_unit)
                )
                if signal.unit.name != observed_name:
                    add(
                        "UNIT_MISMATCH",
                        f"{path}.unit.name",
                        "Claimed unit does not match the unit observed in DatasetProfile.",
                        claimed=signal.unit.name,
                        observed=observed_unit,
                    )
        _check_claim(signal.semantics, f"{path}.semantics", add)

    for index, event_mapping in enumerate(spec.events):
        path = f"events[{index}]"
        _check_reference(
            event_mapping.source_variable,
            VariableRole.EVENT,
            f"{path}.source_variable",
            declared,
            add,
        )
        if event_mapping.source_variable not in observed_schema or not any(
            run.events for run in profile.runs
        ):
            add(
                "INVALID_EVENT_SOURCE",
                f"{path}.source_variable",
                f"Event source {event_mapping.source_variable!r} is not supported by the profile.",
            )
        if event_mapping.time_axis not in axes:
            add(
                "UNKNOWN_TIME_AXIS",
                f"{path}.time_axis",
                f"Time axis {event_mapping.time_axis!r} is not declared.",
            )
        valid_pair = (
            event_mapping.source_index_base is IndexBase.MATLAB_ONE_BASED
            and event_mapping.index_conversion is IndexConversion.SUBTRACT_ONE
        ) or (
            event_mapping.source_index_base is IndexBase.ZERO_BASED
            and event_mapping.index_conversion is IndexConversion.IDENTITY
        )
        if not valid_pair:
            add(
                "INVALID_INDEX_BASE_CONVERSION",
                f"{path}.index_conversion",
                "Index conversion is incompatible with the declared source index base.",
            )
        for run in profile.runs:
            for event in run.events:
                python_index = (
                    event.observed_index - 1
                    if event_mapping.index_conversion is IndexConversion.SUBTRACT_ONE
                    else event.observed_index
                )
                if (
                    run.sequence_length is None
                    or not 0 <= python_index < run.sequence_length
                ):
                    add(
                        "EVENT_INDEX_OUT_OF_BOUNDS",
                        f"{path}.source_variable",
                        f"Event {event.event_id!r} converts to out-of-bounds index {python_index}.",
                        source_run_id=run.source_run_id,
                        observed_index=event.observed_index,
                        converted_index=python_index,
                        sequence_length=run.sequence_length,
                    )
                    continue
                if (
                    event.inferred_time_seconds is not None
                    and run.sampling_rate_hz is not None
                    and run.time_start is not None
                ):
                    expected = run.time_start + python_index / run.sampling_rate_hz
                    if not isclose(
                        event.inferred_time_seconds, expected, rel_tol=0.0, abs_tol=1e-9
                    ):
                        add(
                            "EVENT_TIMESTAMP_MISMATCH",
                            f"{path}.timestamp_rule",
                            f"Event {event.event_id!r} timestamp disagrees with its converted index.",
                            source_run_id=run.source_run_id,
                            converted_index=python_index,
                            expected=expected,
                            observed=event.inferred_time_seconds,
                        )
        _check_claim(event_mapping.semantics, f"{path}.semantics", add)

    available = {
        "source_run_id": all(bool(run.source_run_id) for run in profile.runs),
        "source_files": all(bool(run.source_files) for run in profile.runs),
        "source_subset": bool(profile.source.get("scope")),
        "series_source_id": all(bool(run.source_run_id) for run in profile.runs),
    }
    for index, requirement in enumerate(spec.provenance):
        if requirement.required and not available.get(requirement.field, False):
            add(
                "PROVENANCE_SOURCE_UNAVAILABLE",
                f"provenance[{index}].field",
                f"Required provenance field {requirement.field!r} cannot be produced from the profile.",
            )

    return ValidationResult(valid=not issues, errors=tuple(issues))


def _check_reference(
    name: str, role: VariableRole, path: str, declared: dict[str, Any], add: Any
) -> None:
    variable = declared.get(name)
    if variable is None:
        add(
            "UNDECLARED_SOURCE_VARIABLE",
            path,
            f"Source variable {name!r} is used but not declared in source_variables.",
        )
    elif variable.role is not role:
        add(
            "SOURCE_VARIABLE_ROLE_MISMATCH",
            path,
            f"Source variable {name!r} is declared as {variable.role.value}, expected {role.value}.",
        )


def _check_claim(claim: EvidenceClaim, path: str, add: Any) -> None:
    if claim.status in {EvidenceStatus.DOCUMENTED, EvidenceStatus.INFERRED}:
        if claim.confidence is None or not claim.evidence:
            add(
                "MISSING_EVIDENCE_REFERENCE",
                path,
                f"{claim.status.value.title()} claims require confidence and evidence references.",
            )
        elif any(not reference.strip() for reference in claim.evidence):
            add(
                "INVALID_EVIDENCE_CLAIM",
                path,
                "Evidence references must be non-empty strings.",
            )
    if claim.status is EvidenceStatus.UNRESOLVED and claim.confidence is not None:
        add(
            "INVALID_EVIDENCE_CLAIM",
            path,
            "Unresolved claims must not declare confidence.",
        )


def _normalized_text(value: str) -> str:
    return " ".join(re.findall(r"[a-z0-9]+", value.casefold()))

"""Deterministic validation of semantic DatasetSpecs against DatasetProfiles."""

from __future__ import annotations

from dataclasses import asdict, dataclass, field
import json
from math import isclose
